// Package demo seeds the demo workspace: five sample facilities (a
// hospital, a retail mall, a warehouse, a supermarket and a retail store)
// with their floors, shapes, racks, tables, live data links, style rules
// and reports, so a fresh install has something to look at.
//
// The data lives in pack/, generated by cmd/demo-export from a running
// instance. Seed loads it once, into an empty database, on API start;
// handlers/auth.go then adds every new account to the workspace as an
// editor, and auth.Bootstrap makes the bootstrap admin its owner.
//
// Row ids in the pack are kept as exported (sequences are moved past
// them afterwards); tenant ids are replaced with the new workspace's id.
// Timestamps move forward: each table's rows and row history so that its
// newest row lands at seed time (spacing within a table is kept), and
// everything else by the time since export — so "last 7 days" reports and
// live views look current on the day you install.
package demo

import (
	"bytes"
	"context"
	"embed"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"log/slog"
	"path"
	"strings"
	"time"

	"github.com/Siraj-zaki/spatial-map/backend/internal/store"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// WorkspaceName is the demo workspace's name.
const WorkspaceName = "Demo workspace"

// seededKey marks, in app_settings, that the demo was loaded once — so
// deleting the workspace (or every workspace) never brings it back.
const seededKey = "demo:seeded"

// lockKey serialises concurrent API replicas starting against one
// fresh database.
const lockKey = 0x64656d6f // "demo"

//go:embed all:pack
var pack embed.FS

type manifest struct {
	Version    int       `json:"version"`
	ExportedAt time.Time `json:"exportedAt"`
	Tables     []struct {
		Name string `json:"name"`
		Rows int    `json:"rows"`
	} `json:"tables"`
	Files []struct {
		Key         string `json:"key"`
		ContentType string `json:"contentType"`
	} `json:"files"`
}

// Seed loads the demo workspace when the database has no workspaces and
// the demo was never loaded before. It returns the new workspace's id, or
// 0 when there was nothing to do. Files go to objects first, then every
// row in one transaction, so a failure leaves the database untouched
// (the next start tries again).
func Seed(ctx context.Context, pool *pgxpool.Pool, objects store.ObjectStore) (int64, error) {
	return seed(ctx, pool, objects, pack, time.Now())
}

func seed(ctx context.Context, pool *pgxpool.Pool, objects store.ObjectStore, src fs.FS, now time.Time) (int64, error) {
	// Cheap pre-check outside the transaction: an installed instance
	// never pays for reading the pack.
	if done, err := alreadySeeded(ctx, pool); err != nil || done {
		return 0, err
	}

	man, err := readManifest(src)
	if err != nil {
		return 0, err
	}
	shift := now.Sub(man.ExportedAt)
	perSource, err := sourceShifts(src, now)
	if err != nil {
		return 0, err
	}

	for _, f := range man.Files {
		data, err := fs.ReadFile(src, path.Join("pack", "files", f.Key))
		if err != nil {
			return 0, fmt.Errorf("demo file %s: %w", f.Key, err)
		}
		if err := objects.Put(ctx, f.Key, f.ContentType, data); err != nil {
			return 0, fmt.Errorf("store demo file %s: %w", f.Key, err)
		}
	}

	tx, err := pool.Begin(ctx)
	if err != nil {
		return 0, err
	}
	defer tx.Rollback(ctx)

	if _, err := tx.Exec(ctx, "SELECT pg_advisory_xact_lock($1)", lockKey); err != nil {
		return 0, err
	}
	if done, err := alreadySeeded(ctx, tx); err != nil || done {
		return 0, err
	}

	var tenantID int64
	if err := tx.QueryRow(ctx,
		`INSERT INTO tenants (name, color, is_demo) VALUES ($1, '#0ea5e9', true) RETURNING id`,
		WorkspaceName,
	).Scan(&tenantID); err != nil {
		return 0, fmt.Errorf("create demo workspace: %w", err)
	}

	total := 0
	for _, t := range man.Tables {
		shiftFor := func(map[string]any) time.Duration { return shift }
		if t.Name == "data_source_rows" || t.Name == "data_source_row_events" {
			shiftFor = func(r map[string]any) time.Duration {
				if d, ok := perSource[sourceID(r)]; ok {
					return d
				}
				return shift
			}
		}
		n, err := loadTable(ctx, tx, src, t.Name, tenantID, shiftFor)
		if err != nil {
			return 0, fmt.Errorf("demo table %s: %w", t.Name, err)
		}
		total += n
	}

	if _, err := tx.Exec(ctx,
		`INSERT INTO app_settings (key, value, updated_at) VALUES ($1, to_jsonb($2::bigint), now())
		 ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now()`,
		seededKey, tenantID,
	); err != nil {
		return 0, fmt.Errorf("mark demo seeded: %w", err)
	}
	if err := tx.Commit(ctx); err != nil {
		return 0, err
	}
	slog.Info("demo: seeded demo workspace", "tenant_id", tenantID, "rows", total, "files", len(man.Files))
	return tenantID, nil
}

type querier interface {
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}

func alreadySeeded(ctx context.Context, q querier) (bool, error) {
	var done bool
	err := q.QueryRow(ctx, `
		SELECT EXISTS (SELECT 1 FROM tenants)
		    OR EXISTS (SELECT 1 FROM app_settings WHERE key = $1)`, seededKey).Scan(&done)
	if err != nil {
		return false, fmt.Errorf("demo: check database: %w", err)
	}
	return done, nil
}

func readManifest(src fs.FS) (*manifest, error) {
	b, err := fs.ReadFile(src, "pack/manifest.json")
	if err != nil {
		return nil, fmt.Errorf("demo manifest: %w", err)
	}
	var m manifest
	if err := json.Unmarshal(b, &m); err != nil {
		return nil, fmt.Errorf("demo manifest: %w", err)
	}
	if m.Version != 1 {
		return nil, fmt.Errorf("demo manifest: unsupported version %d", m.Version)
	}
	return &m, nil
}

// loadTable inserts one table's rows with jsonb_populate_recordset, over
// the columns both the pack and the live schema have — a pack exported
// from an older or newer schema still loads. Identity values are kept
// and the id sequence moved past them.
func loadTable(ctx context.Context, tx pgx.Tx, src fs.FS, table string, tenantID int64, shiftFor func(map[string]any) time.Duration) (int, error) {
	rows, err := readRows(src, table)
	if err != nil {
		return 0, err
	}
	if len(rows) == 0 {
		return 0, nil
	}

	inPack := map[string]bool{}
	for _, r := range rows {
		d := shiftFor(r)
		for k, v := range r {
			inPack[k] = true
			r[k] = shiftTimes(v, d)
		}
	}

	colRows, err := tx.Query(ctx, `
		SELECT column_name FROM information_schema.columns
		WHERE table_schema = 'public' AND table_name = $1 AND is_generated = 'NEVER'
		ORDER BY ordinal_position`, table)
	if err != nil {
		return 0, err
	}
	var cols, sel []string
	hasID := false
	for colRows.Next() {
		var c string
		if err := colRows.Scan(&c); err != nil {
			colRows.Close()
			return 0, err
		}
		if c == "id" {
			hasID = true
		}
		switch {
		case c == "tenant_id":
			cols = append(cols, pgx.Identifier{c}.Sanitize())
			sel = append(sel, "$2::bigint")
		case inPack[c]:
			cols = append(cols, pgx.Identifier{c}.Sanitize())
			sel = append(sel, "r."+pgx.Identifier{c}.Sanitize())
		}
	}
	colRows.Close()
	if err := colRows.Err(); err != nil {
		return 0, err
	}
	if len(cols) == 0 {
		return 0, errors.New("table not found")
	}

	payload, err := json.Marshal(rows)
	if err != nil {
		return 0, err
	}
	ident := pgx.Identifier{table}.Sanitize()
	q := fmt.Sprintf(
		"INSERT INTO %s (%s) OVERRIDING SYSTEM VALUE SELECT %s FROM jsonb_populate_recordset(NULL::%s, $1::jsonb) AS r",
		ident, strings.Join(cols, ", "), strings.Join(sel, ", "), ident,
	)
	tag, err := tx.Exec(ctx, q, string(payload), tenantID)
	if err != nil {
		return 0, err
	}

	if hasID {
		if _, err := tx.Exec(ctx, fmt.Sprintf(`
			SELECT setval(seq, GREATEST((SELECT COALESCE(MAX(id), 0) FROM %s), 1))
			FROM pg_get_serial_sequence($1, 'id') AS seq
			WHERE seq IS NOT NULL`, ident), table); err != nil {
			return 0, fmt.Errorf("move id sequence: %w", err)
		}
	}
	return int(tag.RowsAffected()), nil
}

func readRows(src fs.FS, table string) ([]map[string]any, error) {
	b, err := fs.ReadFile(src, path.Join("pack", table+".json"))
	if err != nil {
		return nil, err
	}
	var rows []map[string]any
	dec := json.NewDecoder(bytes.NewReader(b))
	dec.UseNumber()
	if err := dec.Decode(&rows); err != nil {
		return nil, err
	}
	return rows, nil
}

// sourceShifts returns, per table (data source), how far to move its rows
// and row history so the newest of them lands at now.
func sourceShifts(src fs.FS, now time.Time) (map[int64]time.Duration, error) {
	newest := map[int64]time.Time{}
	for _, table := range []string{"data_source_rows", "data_source_row_events"} {
		rows, err := readRows(src, table)
		if errors.Is(err, fs.ErrNotExist) {
			continue
		} else if err != nil {
			return nil, fmt.Errorf("demo table %s: %w", table, err)
		}
		for _, r := range rows {
			id := sourceID(r)
			for _, col := range []string{"ts", "updated_at"} {
				s, _ := r[col].(string)
				if t, err := time.Parse(time.RFC3339Nano, s); err == nil && t.After(newest[id]) {
					newest[id] = t
				}
			}
		}
	}
	out := make(map[int64]time.Duration, len(newest))
	for id, t := range newest {
		out[id] = now.Sub(t)
	}
	return out, nil
}

func sourceID(r map[string]any) int64 {
	n, _ := r["source_id"].(json.Number)
	id, _ := n.Int64()
	return id
}

// shiftTimes moves every RFC 3339 timestamp (columns and values inside
// JSON payloads alike) and every plain YYYY-MM-DD date by d, rounded to
// whole days for dates.
func shiftTimes(v any, d time.Duration) any {
	switch t := v.(type) {
	case string:
		if len(t) >= 20 && t[4] == '-' && t[10] == 'T' {
			if ts, err := time.Parse(time.RFC3339Nano, t); err == nil {
				return ts.Add(d).Format(time.RFC3339Nano)
			}
		}
		if len(t) == 10 && t[4] == '-' && t[7] == '-' {
			if ts, err := time.Parse(time.DateOnly, t); err == nil {
				return ts.AddDate(0, 0, int(d.Hours()/24)).Format(time.DateOnly)
			}
		}
		return t
	case map[string]any:
		for k, c := range t {
			t[k] = shiftTimes(c, d)
		}
		return t
	case []any:
		for i := range t {
			t[i] = shiftTimes(t[i], d)
		}
		return t
	default:
		return v
	}
}
